  }
  int addTransferDirection(mdpTransferDirection? TRANSFER_DIRECTION) {
    fbBuilder.addUint8(11, TRANSFER_DIRECTION?.value);
    return fbBuilder.offset;
  }
  int addOutputTimeBinDays(double? OUTPUT_TIME_BIN_DAYS) {
    fbBuilder.addFloat64(12, OUTPUT_TIME_BIN_DAYS);
    return fbBuilder.offset;
  }
  int addMaxThrustN(double? MAX_THRUST_N) {
    fbBuilder.addFloat64(13, MAX_THRUST_N);
    return fbBuilder.offset;
  }
  int addSpecificImpulseS(double? SPECIFIC_IMPULSE_S) {
    fbBuilder.addFloat64(14, SPECIFIC_IMPULSE_S);
    return fbBuilder.offset;
  }
  int addDryMassKg(double? DRY_MASS_KG) {
    fbBuilder.addFloat64(15, DRY_MASS_KG);
    return fbBuilder.offset;
  }
  int addInitialMassKg(double? INITIAL_MASS_KG) {
    fbBuilder.addFloat64(16, INITIAL_MASS_KG);
    return fbBuilder.offset;
  }
  int addEphemerisSourceOffset(int? offset) {
    fbBuilder.addOffset(17, offset);
    return fbBuilder.offset;
  }
  int addCommentOffset(int? offset) {
    fbBuilder.addOffset(18, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class MDPObjectBuilder extends fb.ObjectBuilder {
  final String? _PROBLEM_ID;
  final String? _NAME;
  final List<MDPEncounterStageObjectBuilder>? _ENCOUNTER_STAGES;
  final List<MDPFlightTimeBoundObjectBuilder>? _FLIGHT_TIME_BOUNDS;
  final double? _MAX_TOTAL_FLIGHT_TIME_DAYS;
  final double? _MAX_LAUNCH_C3_KM2_S2;
  final double? _MAX_TOTAL_DELTA_V_KM_S;
  final mdpDsmMode? _DSM_MODE;
  final double? _MAX_DSM_DELTA_V_KM_S;
  final double? _DSM_GRID_STEP_KM_S;
  final int? _MAX_REVOLUTIONS;
  final mdpTransferDirection? _TRANSFER_DIRECTION;
  final double? _OUTPUT_TIME_BIN_DAYS;
  final double? _MAX_THRUST_N;
  final double? _SPECIFIC_IMPULSE_S;
  final double? _DRY_MASS_KG;
  final double? _INITIAL_MASS_KG;
  final String? _EPHEMERIS_SOURCE;
  final String? _COMMENT;

  MDPObjectBuilder({
    String? PROBLEM_ID,
    String? problemId,
    String? NAME,
    List<MDPEncounterStageObjectBuilder>? ENCOUNTER_STAGES,
    List<MDPEncounterStageObjectBuilder>? encounterStages,
    List<MDPFlightTimeBoundObjectBuilder>? FLIGHT_TIME_BOUNDS,
    List<MDPFlightTimeBoundObjectBuilder>? flightTimeBounds,
    double? MAX_TOTAL_FLIGHT_TIME_DAYS,
    double? maxTotalFlightTimeDays,
    double? MAX_LAUNCH_C3_KM2_S2,
    double? maxLaunchC3Km2S2,
    double? MAX_TOTAL_DELTA_V_KM_S,
    double? maxTotalDeltaVKmS,
    mdpDsmMode? DSM_MODE,
    mdpDsmMode? dsmMode,
    double? MAX_DSM_DELTA_V_KM_S,
    double? maxDsmDeltaVKmS,
    double? DSM_GRID_STEP_KM_S,
    double? dsmGridStepKmS,
    int? MAX_REVOLUTIONS,
    int? maxRevolutions,
    mdpTransferDirection? TRANSFER_DIRECTION,
    mdpTransferDirection? transferDirection,
    double? OUTPUT_TIME_BIN_DAYS,
    double? outputTimeBinDays,
    double? MAX_THRUST_N,
    double? maxThrustN,
    double? SPECIFIC_IMPULSE_S,
    double? specificImpulseS,
    double? DRY_MASS_KG,
    double? dryMassKg,
    double? INITIAL_MASS_KG,
    double? initialMassKg,
    String? EPHEMERIS_SOURCE,
    String? ephemerisSource,
    String? COMMENT,
  })
      : _PROBLEM_ID = problemId ?? PROBLEM_ID,
        _NAME = NAME,
        _ENCOUNTER_STAGES = encounterStages ?? ENCOUNTER_STAGES,
        _FLIGHT_TIME_BOUNDS = flightTimeBounds ?? FLIGHT_TIME_BOUNDS,
        _MAX_TOTAL_FLIGHT_TIME_DAYS = maxTotalFlightTimeDays ?? MAX_TOTAL_FLIGHT_TIME_DAYS,
        _MAX_LAUNCH_C3_KM2_S2 = maxLaunchC3Km2S2 ?? MAX_LAUNCH_C3_KM2_S2,
        _MAX_TOTAL_DELTA_V_KM_S = maxTotalDeltaVKmS ?? MAX_TOTAL_DELTA_V_KM_S,
        _DSM_MODE = dsmMode ?? DSM_MODE,
        _MAX_DSM_DELTA_V_KM_S = maxDsmDeltaVKmS ?? MAX_DSM_DELTA_V_KM_S,
        _DSM_GRID_STEP_KM_S = dsmGridStepKmS ?? DSM_GRID_STEP_KM_S,
        _MAX_REVOLUTIONS = maxRevolutions ?? MAX_REVOLUTIONS,
        _TRANSFER_DIRECTION = transferDirection ?? TRANSFER_DIRECTION,
        _OUTPUT_TIME_BIN_DAYS = outputTimeBinDays ?? OUTPUT_TIME_BIN_DAYS,
        _MAX_THRUST_N = maxThrustN ?? MAX_THRUST_N,
        _SPECIFIC_IMPULSE_S = specificImpulseS ?? SPECIFIC_IMPULSE_S,
        _DRY_MASS_KG = dryMassKg ?? DRY_MASS_KG,
        _INITIAL_MASS_KG = initialMassKg ?? INITIAL_MASS_KG,
        _EPHEMERIS_SOURCE = ephemerisSource ?? EPHEMERIS_SOURCE,
        _COMMENT = COMMENT;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? PROBLEM_IDOffset = _PROBLEM_ID == null ? null
        : fbBuilder.writeString(_PROBLEM_ID!);
    final int? NAMEOffset = _NAME == null ? null
        : fbBuilder.writeString(_NAME!);
    final int? ENCOUNTER_STAGESOffset = _ENCOUNTER_STAGES == null ? null
        : fbBuilder.writeList(_ENCOUNTER_STAGES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? FLIGHT_TIME_BOUNDSOffset = _FLIGHT_TIME_BOUNDS == null ? null
        : fbBuilder.writeList(_FLIGHT_TIME_BOUNDS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? EPHEMERIS_SOURCEOffset = _EPHEMERIS_SOURCE == null ? null
        : fbBuilder.writeString(_EPHEMERIS_SOURCE!);
    final int? COMMENTOffset = _COMMENT == null ? null
        : fbBuilder.writeString(_COMMENT!);
    fbBuilder.startTable(19);
    fbBuilder.addOffset(0, PROBLEM_IDOffset);
    fbBuilder.addOffset(1, NAMEOffset);
    fbBuilder.addOffset(2, ENCOUNTER_STAGESOffset);
    fbBuilder.addOffset(3, FLIGHT_TIME_BOUNDSOffset);
    fbBuilder.addFloat64(4, _MAX_TOTAL_FLIGHT_TIME_DAYS);
    fbBuilder.addFloat64(5, _MAX_LAUNCH_C3_KM2_S2);
    fbBuilder.addFloat64(6, _MAX_TOTAL_DELTA_V_KM_S);
    fbBuilder.addUint8(7, _DSM_MODE?.value);
    fbBuilder.addFloat64(8, _MAX_DSM_DELTA_V_KM_S);
    fbBuilder.addFloat64(9, _DSM_GRID_STEP_KM_S);
    fbBuilder.addUint8(10, _MAX_REVOLUTIONS);
    fbBuilder.addUint8(11, _TRANSFER_DIRECTION?.value);
    fbBuilder.addFloat64(12, _OUTPUT_TIME_BIN_DAYS);
    fbBuilder.addFloat64(13, _MAX_THRUST_N);
    fbBuilder.addFloat64(14, _SPECIFIC_IMPULSE_S);
    fbBuilder.addFloat64(15, _DRY_MASS_KG);
    fbBuilder.addFloat64(16, _INITIAL_MASS_KG);
    fbBuilder.addOffset(17, EPHEMERIS_SOURCEOffset);
    fbBuilder.addOffset(18, COMMENTOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
